void testIso8601()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    assertTrue(isEqual(exchange.iso8601(514862627000), std::string("1986-04-26T01:23:47.000Z")));
    assertTrue(isEqual(exchange.iso8601(514862627559), std::string("1986-04-26T01:23:47.559Z")));
    assertTrue(isEqual(exchange.iso8601(514862627062), std::string("1986-04-26T01:23:47.062Z")));
    assertTrue(isEqual(exchange.iso8601(1), std::string("1970-01-01T00:00:00.001Z")));
    assertTrue(isEqual(exchange.iso8601(-1), std::any{}));
    // assert (exchange.iso8601 () === undefined);
    // todo: assert (exchange.iso8601 () === undefined);
    assertTrue(isEqual(exchange.iso8601(std::any{}), std::any{}));
    assertTrue(isEqual(exchange.iso8601(std::string("")), std::any{}));
    assertTrue(isEqual(exchange.iso8601(std::string("a")), std::any{}));
    assertTrue(isEqual(exchange.iso8601(ccxt::dict {}), std::any{}));
    // NB: every assert below must hold byte-for-byte in every language. Timestamps stay within the
    // year 1970-9999 range, the only range where all the native date implementations agree.
    // 1ms after epoch is asserted above
    assertTrue(isEqual(exchange.iso8601(1000), std::string("1970-01-01T00:00:01.000Z")));
    assertTrue(isEqual(exchange.iso8601(1001), std::string("1970-01-01T00:00:01.001Z")));
    assertTrue(isEqual(exchange.iso8601(86399999), std::string("1970-01-01T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(86400000), std::string("1970-01-02T00:00:00.000Z")));
    // millisecond zero-padding
    assertTrue(isEqual(exchange.iso8601(1755432123005), std::string("2025-08-17T12:02:03.005Z")));
    assertTrue(isEqual(exchange.iso8601(1755432123050), std::string("2025-08-17T12:02:03.050Z")));
    assertTrue(isEqual(exchange.iso8601(1755432123099), std::string("2025-08-17T12:02:03.099Z")));
    assertTrue(isEqual(exchange.iso8601(1755432123500), std::string("2025-08-17T12:02:03.500Z")));
    assertTrue(isEqual(exchange.iso8601(1755432123999), std::string("2025-08-17T12:02:03.999Z")));
    // year rollovers, incl. out of a 366-day leap year
    assertTrue(isEqual(exchange.iso8601(1704067199999), std::string("2023-12-31T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(1704067200000), std::string("2024-01-01T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1735689599999), std::string("2024-12-31T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(1735689600000), std::string("2025-01-01T00:00:00.000Z")));
    // month lengths and boundaries
    assertTrue(isEqual(exchange.iso8601(1706702400000), std::string("2024-01-31T12:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1706788800000), std::string("2024-02-01T12:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1677585600000), std::string("2023-02-28T12:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1677672000000), std::string("2023-03-01T12:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1714521599999), std::string("2024-04-30T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(1714521600000), std::string("2024-05-01T00:00:00.000Z")));
    // leap days: regular leap years, leap centuries and non-leap centuries
    assertTrue(isEqual(exchange.iso8601(68169600000), std::string("1972-02-29T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1709164799999), std::string("2024-02-28T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(1709164800000), std::string("2024-02-29T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(1709251199999), std::string("2024-02-29T23:59:59.999Z")));
    assertTrue(isEqual(exchange.iso8601(1709251200000), std::string("2024-03-01T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(951782400000), std::string("2000-02-29T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(951868800000), std::string("2000-03-01T00:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(4107499200000), std::string("2100-02-28T12:00:00.000Z")));
    assertTrue(isEqual(exchange.iso8601(4107585600000), std::string("2100-03-01T12:00:00.000Z")));
    // others
    // zero is a valid timestamp
    assertTrue(isEqual(exchange.iso8601(0), std::string("1970-01-01T00:00:00.000Z")));
    // plain-integer strings are accepted
    assertTrue(isEqual(exchange.iso8601(std::string("1755432123456")), std::string("2025-08-17T12:02:03.456Z")));
    // strings that are not a plain integer are rejected
    assertTrue(isEqual(exchange.iso8601(std::string("123abc")), std::any{}));
    // non-integer numbers are floored
    assertTrue(isEqual(exchange.iso8601(514862627559.9), std::string("1986-04-26T01:23:47.559Z")));
    // last representable millisecond of year 9999
    assertTrue(isEqual(exchange.iso8601(253402300799999), std::string("9999-12-31T23:59:59.999Z")));
    // one millisecond past the maximum supported range yields undefined
    assertTrue(isEqual(exchange.iso8601(8640000000000001), std::any{}));
    // absurdly large / non-finite magnitudes are rejected too. NaN/Infinity
    // literals don't survive transpilation, but 1e300 does and it exercises the
    // same > 8.64e15 guard in every port (incl. PHP's is_finite branch)
    assertTrue(isEqual(exchange.iso8601(1e+300), std::any{}));
}
void testParse8601()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T01:23:47.000Z")), 514862627000));
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T01:23:47.559Z")), 514862627559));
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T01:23:47.062Z")), 514862627062));
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T01:23:47.06Z")), 514862627060));
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T01:23:47.6Z")), 514862627600));
    assertTrue(isEqual(exchange.parse8601(std::string("1977-13-13T00:00:00.000Z")), std::any{}));
    assertTrue(isEqual(exchange.parse8601(std::string("1986-04-26T25:71:47.000Z")), std::any{}));
    assertTrue(isEqual(exchange.parse8601(std::string("3333")), std::any{}));
    assertTrue(isEqual(exchange.parse8601(std::string("Sr90")), std::any{}));
    assertTrue(isEqual(exchange.parse8601(std::string("")), std::any{}));
    // assert (exchange.parse8601 () === undefined);
    // todo: assert (exchange.parse8601 () === undefined);
    assertTrue(isEqual(exchange.parse8601(std::any{}), std::any{}));
    assertTrue(isEqual(exchange.parse8601(ccxt::dict {}), std::any{}));
    assertTrue(isEqual(exchange.parse8601(33), std::any{}));
}
void testParseDate()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    assertTrue(isEqual(exchange.parseDate(std::string("1986-04-26 00:00:00")), 514857600000));
    assertTrue(isEqual(exchange.parseDate(std::string("1986-04-26T01:23:47.000Z")), 514862627000));
    assertTrue(isEqual(exchange.parseDate(std::string("1986-13-13 00:00:00")), std::any{}));
}
void testMicroseconds()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
    });
    std::any value = exchange.microseconds();
    std::any valueString = toString(value);
    assertTrue(isGreaterThan(value, 0));
    assertTrue(isEqual(getStringLength(valueString), 16));
}
